#!/usr/bin/env python3\n\"\"\"Interactive Paper Trading Demo.\n\nRun this to test different configurations and watch trades execute in real-time.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom app.config import settings\nfrom app.market_data import generate_sample_prices\nfrom app.simulator import run_simulation, generate_signal\nfrom app.reporting import summarize_trades\n\n\ndef run_interactive_demo() -> None:\n    \"\"\"Interactive demo allowing configuration changes.\"\"\"\n    print(\"\\n\" + \"=\"*70)\n    print(\"  K-Eye Forex Trading Bot - Interactive Paper Trading Demo\")\n    print(\"  Version 1.0 | Paper Trading Only | NOT FOR LIVE TRADING\")\n    print(\"=\"*70)\n\n    print(\"\\n📝 Configuration Menu:\")\n    print(\"-\" * 70)\n\n    # Get user inputs\n    try:\n        starting_balance = float(input(f\"Starting balance (default ${settings.starting_balance}): \") or settings.starting_balance)\n        fast_ema = int(input(f\"Fast EMA period (default {settings.fast_ema}): \") or settings.fast_ema)\n        slow_ema = int(input(f\"Slow EMA period (default {settings.slow_ema}): \") or settings.slow_ema)\n        rsi_period = int(input(f\"RSI period (default {settings.rsi_period}): \") or settings.rsi_period)\n        risk_pct = float(input(f\"Risk per trade % (default {settings.risk_per_trade * 100}): \") or settings.risk_per_trade * 100)\n        price_length = int(input(\"Number of price bars to generate (default 60): \") or 60)\n    except ValueError:\n        print(\"❌ Invalid input. Using defaults.\")\n        starting_balance = settings.starting_balance\n        fast_ema = settings.fast_ema\n        slow_ema = settings.slow_ema\n        rsi_period = settings.rsi_period\n        risk_pct = settings.risk_per_trade * 100\n        price_length = 60\n\n    print(\"\\n\" + \"=\"*70)\n    print(\"  Running Simulation...\")\n    print(\"=\"*70 + \"\\n\")\n\n    # Generate prices\n    prices = generate_sample_prices(length=price_length)\n\n    # Run simulation\n    result = run_simulation(\n        price_series=prices.prices,\n        starting_balance=starting_balance,\n        symbol=\"EURUSD\",\n        fast_period=fast_ema,\n        slow_period=slow_ema,\n        rsi_period=rsi_period,\n        risk_per_trade=risk_pct / 100.0,\n        max_positions=1,\n        stop_loss_pct=0.005,\n    )\n\n    # Print results\n    print(\"\\n🎯 Simulation Results:\")\n    print(\"-\" * 70)\n    report = summarize_trades(result.trades, starting_balance)\n\n    print(f\"\\nInitial Balance:     ${starting_balance:.2f}\")\n    print(f\"Final Balance:       ${report.final_balance:.2f}\")\n    print(f\"Net P&L:             ${report.net_pnl:.4f} ({(report.net_pnl/starting_balance)*100:.2f}%)\")\n    print(f\"\\nTotal Trades:        {report.total_trades}\")\n    print(f\"Win Rate:            {report.win_rate:.1f}%\")\n    print(f\"Avg Trade P&L:       ${report.average_trade_pnl:.4f}\")\n\n    if result.trades:\n        print(\"\\n📋 Trade Log:\")\n        print(\"-\" * 70)\n        for i, trade in enumerate(result.trades, 1):\n            status_icon = \"✓\" if trade.status == \"CLOSED\" else \"⧗\"\n            pnl_display = f\"${trade.pnl:.4f}\" if trade.pnl is not None else \"--\"\n            print(\n                f\"{status_icon} Trade {i}: {trade.side:4} @ ${trade.entry_price:.5f} \"\n                f\"({trade.quantity:.2f} units) → P&L: {pnl_display}\"\n            )\n\n    print(\"\\n\" + \"=\"*70)\n    print(\"  Demo Complete!\")\n    print(\"=\"*70 + \"\\n\")\n\n\nif __name__ == \"__main__\":\n    run_interactive_demo()\n"